function Clone($v){$v|ConvertTo-Json -Depth 12|ConvertFrom-Json};function Refuse($v,$label){$ok=$false;try{Assert-R17DelegatedAuthorization $v $prefix $seeds $children $gate $dispatch $attempt|Out-Null}catch{$ok=$true};if(!$ok){throw "invalid authorization accepted: $label"}}
